const body=$json.body??$json;
const action=String(body.action??'chat').trim();
const message=String(body.message??'').trim();
const enquiryId=String(body.enquiry_id??'').trim();
const serviceSlug=String(body.service_slug??'').trim();
const serviceName=String(body.service_name??'').trim();
const date=String(body.date??'').trim();
const time=String(body.time??'').trim();
const fullName=String(body.full_name??'').trim();
const email=String(body.email??'').trim().toLowerCase();
let history=[];try{history=JSON.parse(String(body.history??'[]'));if(!Array.isArray(history))history=[]}catch{}
if(!history.length)history=[{who:'assistant',text:'Hi 👋 Welcome to Favfare. What would you like help with today?'}];
function nextMonday(){const x=new Date();const day=x.getUTCDay();let add=(8-day)%7;if(add===0)add=7;x.setUTCDate(x.getUTCDate()+add);return x.toISOString().slice(0,10)}
let api_url,payload;
if(action==='service_selected'){api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/quote';payload={message:message||('I am interested in '+serviceName),service_slug:serviceSlug,full_name:'WhatsApp Patient',phone:'+2348000000200',whatsapp_id:'favfare-sales-demo-patient'}}
else if(action==='availability'){api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/booking';payload={action:'availability_for_date',preferred_date:date||nextMonday(),enquiry_id:enquiryId}}
else if(action==='request_booking'){api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/booking';payload={action:'request_booking',enquiry_id:enquiryId,preferred_date:date,preferred_time:time}}
else if(action==='capture_email'){api_url='https://shftukueyostzbyqxmqw.supabase.co/functions/v1/favfare-demo-contact';payload={enquiry_id:enquiryId,full_name:fullName,phone:'+2348000000200',email,whatsapp_id:'favfare-sales-demo-patient'}}
else{api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/crm';payload={action:action==='chat'?'catalogue':'health'}}
return[{json:{action,message,enquiry_id:enquiryId,service_slug:serviceSlug,service_name:serviceName,date:date||nextMonday(),time,full_name:fullName,email,history,api_url,payload}}];

const d=$json??{};const c=$('Normalize Action').first().json;
const esc=(v)=>String(v??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
let h=Array.isArray(c.history)?[...c.history]:[];const say=(who,text)=>{h.push({who,text:String(text)});};
const hidden=(n,v)=>'<input type="hidden" name="'+esc(n)+'" value="'+esc(v)+'">';
const hist=()=>hidden('history',JSON.stringify(h));
const state=()=>hist()+hidden('enquiry_id',c.enquiry_id)+hidden('service_slug',c.service_slug)+hidden('service_name',c.service_name)+hidden('date',c.date)+hidden('time',c.time)+hidden('full_name',c.full_name)+hidden('email',c.email);
const postButton=(action,label,extra='')=>'<form method="post" action="/webhook/favfare-demo/patient-action">'+hidden('action',action)+state()+extra+'<button>'+esc(label)+'</button></form>';
const composer=()=>'<form class="composer" method="post" action="/webhook/favfare-demo/patient-action">'+hidden('action','chat')+state()+'<input name="message" placeholder="Type a message" autocomplete="off" required><button>➤</button></form>';
const pretty=(iso)=>new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const services=Array.isArray(d.services)?d.services:[];
const bySlug=(s)=>services.find(x=>x.slug===s);
const serviceRow=(s)=>{if(!s)return'';const safe=s.demo_seed_status==='approved'&&!s.needs_clinic_confirmation&&s.price_display;const meta=safe?' · '+s.price_display:'';return postButton('service_selected',s.name+meta,hidden('service_slug',s.slug)+hidden('service_name',s.name)+hidden('message','I am interested in '+s.name));};
const serviceList=(items)=>'<div class="list">'+items.filter(Boolean).map(serviceRow).join('')+'</div>';
const popular=()=>serviceList(['scaling-and-polishing','teeth-whitening-generic','medical-braces','veneers','composite-bonding-broken-tooth','dentures'].map(bySlug));
let controls='';
if(c.action==='chat'){const m=c.message.toLowerCase();if(c.message)say('patient',c.message);
 if(/pain|swelling|bleeding|infection|diagnos|medicine|medication|what is wrong/.test(m)){say('assistant','I can help with clinic information and booking, but I can’t diagnose symptoms in chat. A Favfare team member should review that with you.');controls='<div class="quick">'+postButton('chat','Talk to staff',hidden('message','I want to speak to a staff member'))+postButton('chat','View services',hidden('message','Show me your services'))+'</div>';}
 else if(/talk to staff|human|person|someone/.test(m)){say('assistant','Of course. I’ll keep this as a staff-handled request rather than guessing. You can also keep browsing services while the team follows up.');controls='<div class="quick">'+postButton('chat','View services',hidden('message','Show me your services'))+'</div>';}
 else if(/clean|cleaning|scale|polish|stain/.test(m)){say('assistant','Sure — are you mainly looking for a regular cleaning, or do you have tougher stains you want removed?');controls='<div class="quick">'+serviceRow(bySlug('scaling-and-polishing'))+serviceRow(bySlug('tough-stain-removal-scaling-polishing'))+'</div>';}
 else if(/white|whiten|bright/.test(m)){say('assistant','Absolutely. Favfare has several whitening options. I can show you the available options, then help you decide what to ask the clinic about.');controls=serviceList(services.filter(x=>String(x.slug).includes('whitening')));}
 else if(/service|option|offer|treatment/.test(m)){say('assistant','Sure. Here are some of Favfare’s popular services. Choose one and I’ll take you from there.');controls=popular();}
 else if(/book|appointment|available|schedule/.test(m)){say('assistant','Absolutely. What service are you looking to book?');controls=popular();}
 else if(/brace/.test(m)){say('assistant','Favfare offers medical braces. I can show that option, but I won’t guess an unconfirmed price.');controls=serviceList([bySlug('medical-braces')]);}
 else if(/veneer/.test(m)){say('assistant','Favfare offers veneer treatments. Choose the option below and I’ll tell you what I can confirm from the clinic data.');controls=serviceList([bySlug('veneers'),bySlug('composite-veneer')]);}
 else if(/chipped|broken|bonding/.test(m)){say('assistant','Yes — Favfare has options for chipped or broken teeth. Here are the relevant services I found.');controls=serviceList([bySlug('chipped-tooth'),bySlug('composite-bonding-broken-tooth')]);}
 else if(/hi|hello|hey|good morning|good afternoon|good evening/.test(m)){say('assistant','Hi 👋 What are you looking to improve — cleaning, whitening, fixing a tooth, or something else?');controls='<div class="quick">'+postButton('chat','Cleaning',hidden('message','I want to clean my teeth'))+postButton('chat','Whitening',hidden('message','I want whiter teeth'))+postButton('chat','Fix a tooth',hidden('message','I have a chipped tooth'))+postButton('chat','View services',hidden('message','Show me your services'))+'</div>';}
 else{say('assistant','I can help you compare Favfare services, check approved prices, and request an appointment. What are you hoping to improve?');controls='<div class="quick">'+postButton('chat','View services',hidden('message','Show me your services'))+postButton('chat','Book appointment',hidden('message','I want to book an appointment'))+'</div>';}
}
else if(c.action==='service_selected'){say('patient','I’m interested in '+(c.service_name||'that service')+'.');if(d.enquiry_id){say('assistant',d.reply||'I found the service. Would you like me to check availability?');controls='<div class="quick">'+postButton('availability','Check availability')+postButton('chat','Ask a question',hidden('message','I have a question about '+c.service_name))+'</div>';}else{say('assistant','Favfare does offer '+(c.service_name||'that service')+'. I don’t want to give you an unconfirmed price here, so I’d rather have the clinic confirm it than guess.');controls='<div class="quick">'+postButton('chat','View other services',hidden('message','Show me your services'))+postButton('chat','Talk to staff',hidden('message','I want to speak to a staff member'))+'</div>';}}
else if(c.action==='availability'){say('patient','Yes, please check availability.');const slots=Array.isArray(d.slots)?d.slots.slice(0,8):[];if(slots.length){say('assistant','I found these available times for '+pretty(c.date)+'. Which works best for you?');controls='<div class="slots">'+slots.map(x=>{const s=String(x).slice(0,5);return postButton('choose_time',s,hidden('time',s));}).join('')+'</div>';}else{say('assistant','I couldn’t find an available demo slot on that date. Let me show you the services again or you can ask the team for another day.');controls='<div class="quick">'+postButton('chat','View services',hidden('message','Show me your services'))+postButton('chat','Talk to staff',hidden('message','I want to speak to a staff member'))+'</div>';}}
else if(c.action==='choose_time'){say('patient',c.time);say('assistant','That time is available right now. Before I send the appointment request, what full name should I put on it?');controls='<form class="single" method="post" action="/webhook/favfare-demo/patient-action">'+hidden('action','capture_name')+state()+'<input name="full_name" placeholder="Your full name" autocomplete="name" required><button>Continue</button></form>';}
else if(c.action==='capture_name'){say('patient',c.full_name);say('assistant','Thanks, '+c.full_name+'. What email address should Favfare attach to the booking?');controls='<form class="single" method="post" action="/webhook/favfare-demo/patient-action">'+hidden('action','capture_email')+state()+'<input type="email" name="email" placeholder="Email address" autocomplete="email" required><button>Continue</button></form><div class="detected">Your WhatsApp phone number is already captured automatically.</div>';}
else if(c.action==='capture_email'){say('patient',c.email);if(d.ok){say('assistant','Perfect. I have your name, email, and WhatsApp number. Please confirm that you want me to send the appointment request for '+pretty(c.date)+' at '+c.time+'.');controls='<div class="summary"><strong>'+esc(c.service_name||'Favfare service')+'</strong><span>'+esc(pretty(c.date))+' · '+esc(c.time)+'</span><span>'+esc(c.full_name)+' · '+esc(c.email)+'</span></div>'+postButton('request_booking','Send appointment request');}else{say('assistant','I couldn’t save those details just now. Please try again.');controls=postButton('capture_name','Try again');}}
else if(c.action==='request_booking'){say('patient','Yes, send the request.');if(d.ok){say('assistant',d.reply||'Your appointment request has been recorded.');say('assistant','A Favfare team member still needs to confirm it. I’ve saved the request in the clinic CRM for staff review.');controls='<div class="actions"><a href="/webhook/favfare-demo/crm-ui" target="_blank">Open staff CRM →</a><a class="secondary" href="/webhook/favfare-demo/patient">Start a new demo</a></div>';}else{say('assistant','That slot is no longer available. I can check again for another time.');controls=postButton('availability','Check other times');}}
const bubbles=h.map(x=>'<div class="msg '+(x.who==='patient'?'patient':'assistant')+'"><div class="bubble">'+esc(x.text)+'</div></div>').join('');
const html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Favfare Patient Assistant</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#e7eee9;color:#17241e;min-height:100vh;display:grid;place-items:center;padding:22px}.wrap{width:min(1050px,100%);display:grid;grid-template-columns:1fr 400px;gap:38px;align-items:center}.intro small{font-weight:850;letter-spacing:.14em;color:#426454}.intro h1{font-size:44px;letter-spacing:-.04em;margin:10px 0}.intro p{color:#65716b;line-height:1.7;max-width:560px}.note{background:white;padding:18px;border-radius:18px;margin-top:24px;border:1px solid #d9e3dc}.note span{font-size:12px;color:#6a756f}.back{display:inline-block;margin-top:16px;color:#2e5b49;font-weight:750;text-decoration:none}.phone{height:760px;max-height:90vh;background:#efeae2;border-radius:26px;overflow:hidden;box-shadow:0 24px 70px rgba(16,50,36,.22);display:flex;flex-direction:column}.top{background:#075e54;color:white;padding:14px 16px;display:flex;gap:12px;align-items:center}.avatar{width:42px;height:42px;border-radius:50%;background:white;color:#075e54;display:grid;place-items:center;font-weight:900}.top strong{display:block}.top span{font-size:12px;opacity:.82}.status{font-size:11px;padding:7px 12px;background:#fff7cf;text-align:center;color:#715800}.chat{flex:1;overflow:auto;padding:18px 14px;background-image:radial-gradient(rgba(0,0,0,.025) 1px,transparent 1px);background-size:18px 18px}.msg{display:flex;margin:9px 0}.msg.patient{justify-content:flex-end}.bubble{max-width:84%;padding:10px 12px;border-radius:9px;line-height:1.45;font-size:14px;box-shadow:0 1px 1px rgba(0,0,0,.08)}.assistant .bubble{background:white;border-top-left-radius:2px}.patient .bubble{background:#d9fdd3;border-top-right-radius:2px}.controls{padding:10px;background:#f0f2f5}.quick{display:grid;grid-template-columns:1fr 1fr;gap:7px}.quick form,.slots form,.list form{margin:0}.quick button,.slots button,.list button{width:100%;border:1px solid #a9c7b8;background:white;color:#12624c;padding:10px;border-radius:12px;font-weight:750;cursor:pointer}.list{display:grid;gap:7px}.list button{text-align:left}.slots{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.composer{display:flex;gap:8px;margin-top:8px}.composer input,.single input{flex:1;border:1px solid #d7dfda;border-radius:22px;padding:12px 15px;font-size:14px;outline:none;background:white}.composer button{width:44px;height:44px;border:0;border-radius:50%;background:#00a884;color:white;font-size:18px}.single{display:flex;gap:8px}.single button{border:0;border-radius:12px;padding:0 15px;background:#00a884;color:white;font-weight:800}.detected{font-size:10px;color:#6f7c76;margin-top:6px}.summary{display:grid;gap:3px;background:white;border:1px solid #d7dfda;border-radius:12px;padding:12px;margin-bottom:8px}.summary span{font-size:12px;color:#66736d}.actions{display:grid;gap:8px}.actions a{display:block;text-align:center;text-decoration:none;background:#075e54;color:white;padding:11px;border-radius:12px;font-weight:800}.actions .secondary{background:white;color:#075e54;border:1px solid #a9c7b8}@media(max-width:850px){.wrap{grid-template-columns:1fr}.intro h1{font-size:34px}.phone{height:78vh}}</style></head><body><div class="wrap"><section class="intro"><small>BIZI SYSTEMS · LIVE SALES DEMO</small><h1>Favfare Patient Assistant</h1><p>The assistant leads with conversation, asks one useful question at a time, and only switches to structured service or time choices when that makes the patient’s decision easier.</p><div class="note"><strong>Current decision layer</strong><br><span>Deterministic sales-demo planner using live Favfare catalogue and booking data. The provider adapter is ready for an LLM once an AI API credential is added.</span></div><a class="back" href="/webhook/favfare-demo/crm-ui" target="_blank">Open staff CRM ↗</a></section><section class="phone"><div class="top"><div class="avatar">F</div><div><strong>Favfare The Clinic</strong><span>Patient Assistant · online</span></div></div><div class="status">Demo · WhatsApp number auto-captured · staff confirms bookings</div><div class="chat">'+bubbles+'</div><div class="controls">'+controls+((c.action==='request_booking'&&d.ok)?'':composer())+'</div></section></div></body></html>';return[{json:{html}}];
